def _decode_body(payload):
    """Recursively decode an email body, preferring text/plain."""
    data = payload.get("body", {}).get("data")
    if data and payload.get("mimeType", "").startswith("text/"):
        return base64.urlsafe_b64decode(data).decode("utf-8", errors="replace")
    best = ""
    for part in payload.get("parts", []):
        decoded = _decode_body(part)            # actually recurse into nested multiparts
        if not decoded:
            continue
        if part.get("mimeType") == "text/plain":
            return decoded                      # plain text wins immediately
        best = best or decoded
    return best
